// ประกอบข้อความสำหรับ Groq จากโปรไฟล์ที่เว็บส่งมา
// เว็บเป็นผู้กำหนดโดเมน — n8n ไม่ต้องแก้เมื่อเปลี่ยนธุรกิจ
const { query, profile } = $json.body ?? {};

if (!query) {
  throw new Error('payload ไม่มี field "query"');
}

const systemPrompt =
  profile?.systemPrompt ?? 'คุณเป็นผู้ช่วยตอบคำถามของผู้ใช้อย่างสุภาพ';

const categories = Array.isArray(profile?.categories) ? profile.categories : [];

const userMessage = [
  'โดเมนของระบบ: ' + (profile?.domain ?? 'ไม่ระบุ'),
  'หมวดที่ระบบมี: ' + (categories.join(', ') || 'ไม่ระบุ'),
  '',
  'คำถามจากผู้ใช้: ' + query,
].join('\n');

return [
  {
    json: {
      model: 'llama-3.3-70b-versatile',
      temperature: 0.3,
      max_completion_tokens: 400,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage },
      ],
    },
  },
];

// ดึงคำตอบจาก Groq และบังคับให้อยู่ในรูปแบบที่เว็บคาดหวัง
const response = $input.first().json ?? {};
const raw = response?.choices?.[0]?.message?.content ?? '';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  // โมเดลตอบออกมาไม่ใช่ JSON — ใช้ข้อความดิบแทน
  parsed = { answer: raw };
}

const answer = typeof parsed.answer === 'string' ? parsed.answer.trim() : '';

const suggestions = Array.isArray(parsed.suggestions)
  ? parsed.suggestions
      .filter((item) => typeof item === 'string' && item.trim().length > 0)
      .slice(0, 3)
  : [];

return [
  {
    json: {
      answer:
        answer || 'ขออภัยครับ ตอนนี้ยังไม่สามารถตอบคำถามนี้ได้ ลองถามใหม่อีกครั้ง',
      suggestions,
      model: response?.model ?? null,
      usage: response?.usage ?? null,
    },
  },
];
